mapper.select:
SELECT IFNULL(MAX(room_id), 0)
FROM chat_room
WHERE trade_id = #{trade_id} AND buyer_id = #{buyer_id}

mapper.update:
UPDATE chat_message
SET is_read = 'Y'
WHERE room_id = #{room_id} 
  AND sender_id != #{reader_id} 
  AND is_read = 'N'

UPDATE chat_room
SET is_flagged = 'Y'
WHERE room_id = #{room_id}

UPDATE chat_room
SET admin_closed = 'Y'
WHERE room_id = #{room_id}
